import XCTest
@testable import Kestrel

/// vectors.json was generated by the previous React Native app's own wallet
/// code (@scure/bip39, @scure/bip32, @noble/curves). The Swift wallet must
/// match it byte for byte so existing recovery phrases restore the same
/// address and signatures are accepted by the TRON network.
final class CryptoVectorTests: XCTestCase {
    struct Vectors: Decodable {
        struct Wallet: Decodable {
            let mnemonic, seed, privateKey, address, txID, signature: String
        }
        let keccakEmpty, keccakAbc: String
        let wallets: [Wallet]
    }

    private func load() throws -> Vectors {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "vectors", withExtension: "json"))
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testKeccak() throws {
        let v = try load()
        XCTAssertEqual(Hex.encode(Keccak256.hash([])), v.keccakEmpty)
        XCTAssertEqual(Hex.encode(Keccak256.hash(Array("abc".utf8))), v.keccakAbc)
        // Longer than one 136-byte block.
        XCTAssertEqual(Keccak256.hash([UInt8](repeating: 0x61, count: 300)).count, 32)
    }

    func testWalletsMatchPreviousApp() throws {
        for w in try load().wallets {
            XCTAssertTrue(Mnemonic.isValid(w.mnemonic))
            XCTAssertEqual(Hex.encode(Mnemonic.seed(from: w.mnemonic)), w.seed)
            let keys = try TronKeys(mnemonic: w.mnemonic)
            XCTAssertEqual(Hex.encode(keys.privateKey), w.privateKey)
            XCTAssertEqual(keys.address, w.address)
            XCTAssertEqual(try keys.sign(transactionID: w.txID), w.signature)
            XCTAssertTrue(TronAddress.isValid(w.address))
        }
    }

    func testMnemonicGenerationAndValidation() throws {
        XCTAssertEqual(Mnemonic.wordlist.count, 2048)
        for _ in 0 ..< 20 {
            let phrase = try Mnemonic.generate()
            XCTAssertEqual(phrase.split(separator: " ").count, 12)
            XCTAssertTrue(Mnemonic.isValid(phrase))
        }
        // Valid words, bad checksum.
        XCTAssertFalse(Mnemonic.isValid("abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon"))
        XCTAssertFalse(Mnemonic.isValid("not a real phrase"))
        XCTAssertTrue(Mnemonic.isValid("  Abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon ABOUT \n"))
    }

    func testAddressValidation() {
        XCTAssertTrue(TronAddress.isValid("TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t")) // USDT contract
        XCTAssertFalse(TronAddress.isValid("TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6u")) // checksum typo
        XCTAssertFalse(TronAddress.isValid("0x742d35Cc6634C0532925a3b844Bc454e4438f44e"))
        XCTAssertEqual(TronAddress.hex21("TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t"), "41a614f803b6fd780986a42c78ec9c7f77e6ded13c")
    }

    func testAmountParsing() {
        XCTAssertEqual(USDT.units(from: "1.5"), 1_500_000)
        XCTAssertEqual(USDT.units(from: "0.000001"), 1)
        XCTAssertEqual(USDT.units(from: "12"), 12_000_000)
        XCTAssertNil(USDT.units(from: "1.2.3"))
        XCTAssertNil(USDT.units(from: "1.0000001")) // more than 6 decimals
        XCTAssertEqual(USDT.format(units: 1_234_567_890), "1,234.56")
    }
}
